
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_6_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_6", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.784732852909829e+00, -4.690644831466181e+00, -4.558825498917199e+00, -4.376259850900849e+00, -4.127545865466470e+00, -3.796558263455414e+00, -3.370275884370841e+00, -2.844954846353778e+00, -2.231740556430267e+00, -1.563269376526813e+00, -9.650127907013650e-01, -6.723597367281753e-01, -6.175399948230609e-01, -5.236667399076733e-01, -3.691555700207347e-01, -2.146368995020607e-01, -9.769705791422216e-02, -3.262790651608056e-02, -7.012024255074273e-03, -7.891232911827932e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


